                  }`}>
                    <p className="text-[15px] leading-relaxed whitespace-pre-wrap">{m.text}</p>
                    {m.role === 'model' && (
                      <span className="absolute -top-6 left-0 text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Bhai</span>
                    )}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                  <div className="bg-slate-100 p-4 rounded-2xl rounded-tl-none border border-slate-200">
                    <div className="flex gap-1">
                      <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                      <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
